    "C08","C09","C13","C20","C12","C14","C06","C18","C01","C03","C10","C19",
    "C02","C16","C04","C07","C11","C17","C49","C50","C47","C51","C45","C66"
  ],
  "claims": [
    {
      "claim": "All transferable L1 gold records report absolute or systemic oral bioavailability at or above 20%: ranitidine 54±22% and 58±11% in cirrhosis; didanosine 26±5%, 35±5%, and 29±6%; nitecapone 38–59%; thalidomide probably high/80–100%; tegafur almost 100%; chloramphenicol excellent or >100% in children; (R)- and (S)-thalidomide around 80–100%.",
      "card_ids": ["C08","C09","C13","C20","C12","C14","C06","C18","C01","C03","C10","C19","C02","C16","C04","C07","C11","C17"]
    },
    {
      "claim": "L4 in vivo absorption records for close nitrofuran/hydantoin analogs show high fraction absorbed: dantrolene ~80% in normal subjects and high absorption in rats irrespective of gastric pH; nitrofurazone 88% absorbed in rats; furazolidone minimum ~75% absorption in rats.",
      "card_ids": ["C49","C50","C47","C51","C45"]
    },
    {
      "claim": "L5 gut-wall/efflux records for dantrolene, a close hydantoin-nitrofuran analog, show high bidirectional permeability (Papp A-B 300 nm/s) and efflux ratio 1, indicating no efflux liability; repeated cards are duplicates and not independent evidence.",
      "card_ids": ["C66"]
    },
    {
      "claim": "L6 hepatic-clearance records show nitrofurazone has a short perfusate half-life (5.34±2.03 and 6.19±1.47 min) in isolated perfused rat liver, but these are analog/rat/in vitro assays and do not quantify oral F for the query; they introduce uncertainty but do not affirm F<20%.",
      "card_ids": ["C73","C68"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C73","C68"]
    }
  ],
  "evidence_gaps": [
    "No direct nitrofurantoin-specific absolute oral bioavailability record is supplied.",
    "No matched oral-versus-IV AUC data for the query are available.",
    "L4/L5/L6 data are from close analogs (dantrolene, nitrofurazone, furazolidone), not from the query itself.",
    "L6 hepatic-clearance endpoints are perfusate half-life/intrinsic clearance, not oral F or extraction ratio; they cannot be converted into a quantitative Fh for the query.",
    "Nitrofurazone (semicarbazone) differs from the query (hydantoin imine), limiting transfer of metabolic-stability results.",
    "Repeated L5/L6 cards are duplicates and not independent evidence."
  ],
  "decision_summary": "Predicted high (F>=20%) because all transferable L1 gold records are at/above 20%, close nitrofuran/hydantoin analogs show high absorption and permeability with no efflux, and L6 hepatic-clearance evidence, while indicating metabolic liability for nitrofurazone in rat liver, is analog/in vitro and does not affirm F<20% for the query. Confidence is moderate due to lack of direct query F data and the new hepatic-clearance uncertainty."
}

